import {createChatOrchestrator} from './chatOrchestrator.js';
import {createMockProvider} from '../providers/mock/mockProvider.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
import type {ChatSession} from '../types/session.js';

// @spec specs/hal-engine-config-hooks/spec.md#8
it('preserves a thrown string as the onError cause and caller rejection', async () => {
  const rejection = 'session unavailable';
  const observed: Error[] = [];
  const session: ChatSession = {sessionId: 's1', userId: 'u1', entries: []};
  const orchestrator = createChatOrchestrator(
    createMockProvider(),
    new PromptBuilder({identity: 'Test assistant'}),
    undefined,
    {
      hooks: {
        beforeSession: async () => {
          throw rejection;
        },
        onError: async (_session, error) => {
          observed.push(error);
        },
      },
    }
  );

  const outcome: unknown = await orchestrator.processMessage(session).catch((error: unknown) => error);

  expect({outcome, count: observed.length, isError: observed[0] instanceof Error, message: observed[0]?.message, cause: observed[0]?.cause}).toEqual({
    outcome: rejection,
    count: 1,
    isError: true,
    message: rejection,
    cause: rejection,
  });
});
EOF
 timeout 300 npm test -- --runTestsByPath src/orchestration/onErrorCause.test.ts --runInBand"
